740	        return;
741	      }
742	      const status = error instanceof HttpError ? error.status : 500;
743	      const code = error instanceof HttpError ? error.code
744	        : error instanceof SnapshotError ? error.code
745	          : 'INTERNAL_ERROR';
746	      const payload = { code, message: error.message };
747	      if (Array.isArray(error.conflicts)) payload.conflicts = error.conflicts;
748	      sendJson(res, status, payload);
749	    });
750	  });
751	  return server;
752	}
