26	async function startServer(args, { cwd } = {}) {
27	  const child = spawn(process.execPath, [CLI, 'serve', ...args], { cwd, stdio: ['ignore', 'pipe', 'pipe'] });
28	  let stdout = '';
29	  let stderr = '';
30	  child.stdout.on('data', (chunk) => { stdout += chunk; });
31	  child.stderr.on('data', (chunk) => { stderr += chunk; });
32	  const address = await new Promise((resolve, reject) => {
33	    child.stdout.on('data', () => {
34	      const index = stdout.indexOf('\n');
35	      if (index === -1) return;
36	      try {
37	        resolve(JSON.parse(stdout.slice(0, index)));
38	      } catch (error) {
39	        reject(error);
40	      }
41	    });
42	    child.on('exit', (code) => reject(new Error(`server exited with status ${code}: ${stderr.trim()}`)));
43	  });
44	  return {
45	    child,
46	    address,
47	    url: `http://${address.host}:${address.port}`,
48	    stdout: () => stdout,
49	    stderr: () => stderr,
50	    stop: () => new Promise((resolve) => {
51	      child.once('exit', resolve);
52	      child.kill('SIGKILL');
53	    }),
