import('./src/workspace.js').then(({Workspace}) => {
  const w = new Workspace();
  w.add({ id: 'a', title: '项目计划', body: 'See [[b]].', tags: ['X'] });
  w.add({ id: 'b', title: 'Plan', body: 'back to [[a]]', tags: [] });
  w.add({ id: 'c', title: 'plan', body: 'case-sensitive sibling', tags: [] });
  const snapshot = w.exportJSON();
  // The exported snapshot must always re-import cleanly now.
  const target = new Workspace();
  target.importJSON(JSON.stringify(snapshot), { mode: 'replace' });
  console.log('round-trip ok:', target.exportJSON().checksum === snapshot.checksum);
  // Merge of the same snapshot onto itself also stays conflict-free.
  const merged = w.importJSON(snapshot, { mode: 'merge' });
  console.log('self-merge ok:', merged.checksum === snapshot.checksum);
});
" && npm run demo --silent >/dev/null && echo "demo ok"
